+import type { OrderDiscount } from "../types.js";
+
+/**
+ * Discount strategies keyed by `OrderDiscount.type`.
+ *
+ * Each strategy receives the current subtotal (in cents) and the
+ * discount value, and returns the amount to deduct (also in cents).
+ * Results are always clamped to [0, subtotalCents].
+ */
+const discountStrategies: Record<
+  OrderDiscount["type"],
+  (subtotalCents: number, value: number) => number
+> = {
+  percentage(subtotalCents, value) {
+    const pct = Math.max(0, Math.min(100, value));
+    return Math.round((subtotalCents * pct) / 100);
+  },
+
+  fixed_cents(subtotalCents, value) {
+    return Math.min(subtotalCents, Math.max(0, value));
+  },
+};
+
+/**
+ * Returns the discount amount in cents for the given subtotal.
+ * Returns 0 when no discount is provided or the type is unrecognised.
+ */
+export function calculateDiscount(
+  subtotalCents: number,
+  discount?: OrderDiscount
+): number {
+  if (!discount) return 0;
+
+  const strategy = discountStrategies[discount.type];
+  if (!strategy) return 0;
+
+  return strategy(subtotalCents, discount.value);
+}
