@@ -0,0 +1,29 @@
+import type { OrderItem } from "../types.js";
+
+export interface ItemTotals {
+  subtotalCents: number;
+  itemCount: number;
+}
+
+/**
+ * Validates every item in the order and computes the raw subtotal
+ * (sum of unitPriceCents × quantity) and the total unit count.
+ *
+ * Throws if any item carries a non-positive quantity or a negative price.
+ */
+export function calculateItemTotals(items: OrderItem[]): ItemTotals {
+  let subtotalCents = 0;
+  let itemCount = 0;
+
+  for (const item of items) {
+    if (item.quantity <= 0 || item.unitPriceCents < 0) {
+      throw new Error(
+        `Invalid item quantity or price for item ${item.id}`
+      );
+    }
+    subtotalCents += item.unitPriceCents * item.quantity;
+    itemCount += item.quantity;
+  }
+
+  return { subtotalCents, itemCount };
+}
